import { createContext, type ReactNode, useContext, useEffect, useMemo, useRef } from "react";

const CDN_URL = "https://feediyo.com/sdk/v1/fdy.js";
const SCRIPT_ID = "fdy-sdk";

// ─── Types ───────────────────────────────────────────────────────────────────

export type Position = "left" | "right";
export type Theme = "light" | "dark" | "auto";

export interface IdentifyPayload {
  id: string;
  email: string;
  name?: string;
  /** HMAC-SHA256 signature generated server-side */
  signature?: string;
  /**
   * Opaque token generated by `createFeediyoAuth()` on your server.
   * When present, `createAutoLoginUrl()` will embed it so the user lands
   * on the public board already signed in — no extra login prompt.
   */
  clientToken?: string;
}

interface FeediyoSDK {
  init(projectId: string, options?: { position?: Position; theme?: Theme }): void;
  identify(user: IdentifyPayload | null): void;
  showWidget(): void;
  hideWidget(): void;
  setTheme(theme: Theme): void;
  destroy(): void;
}

declare global {
  interface Window {
    feediyo: FeediyoSDK;
    $fdyq: [string, ...unknown[]][];
  }
}

// ─── Context ─────────────────────────────────────────────────────────────────

export interface FeediyoContextValue {
  identify(user: IdentifyPayload | null): void;
  showWidget(): void;
  hideWidget(): void;
  setTheme(theme: Theme): void;
  /**
   * Wraps a public board URL with the current user's clientToken so they land
   * already signed in. Falls back to the original href if no user is identified
   * or no clientToken is present.
   *
   * @example
   * const { createAutoLoginUrl } = useFeediyo();
   * <a href={createAutoLoginUrl("https://feedback.example.com")}>View roadmap</a>
   */
  createAutoLoginUrl(href: string): string;
}

const FeediyoContext = createContext<FeediyoContextValue | null>(null);

// ─── Helpers ─────────────────────────────────────────────────────────────────

function setupQueue() {
  window.$fdyq = window.$fdyq || [];
  window.feediyo =
    window.feediyo ||
    new Proxy({} as FeediyoSDK, {
      get:
        (_, method: string) =>
        (...args: unknown[]) =>
          window.$fdyq.push([method, ...args]),
    });
}

function injectScript() {
  if (document.getElementById(SCRIPT_ID)) return;
  const s = Object.assign(document.createElement("script"), {
    id: SCRIPT_ID,
    src: CDN_URL,
    async: true,
  });
  document.head.appendChild(s);
}

function removeScript() {
  document.getElementById(SCRIPT_ID)?.remove();
}

// ─── Provider ────────────────────────────────────────────────────────────────

export interface FeediyoProviderProps {
  projectId: string;
  position?: Position;
  theme?: Theme;
  /**
   * Pass your logged-in user to auto-identify them.
   * Include `signature` and `clientToken` from `createFeediyoAuth()` on your
   * server to enable identity verification and automatic login on the public board.
   * Set to null on logout. Omit entirely for anonymous-only use.
   */
  user?: IdentifyPayload | null;
  children: ReactNode;
}

export function FeediyoProvider({
  projectId,
  position = "right",
  theme = "auto",
  user,
  children,
}: FeediyoProviderProps) {
  // Stable ref so createAutoLoginUrl always reads the latest token without
  // invalidating the memoised context value.
  const clientTokenRef = useRef<string | null>(null);

  useEffect(() => {
    setupQueue();
    window.feediyo.init(projectId, { position, theme });
    injectScript();
    return () => {
      window.feediyo?.destroy?.();
      removeScript();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, position, theme]);

  // Sync identity whenever the logged-in user changes.
  // Skipped entirely when the `user` prop is omitted (anonymous mode).
  useEffect(() => {
    if (typeof window === "undefined" || user === undefined) return;
    clientTokenRef.current = user?.clientToken ?? null;
    window.feediyo.identify(user);
  }, [user?.id, user?.clientToken, user]);

  const value = useMemo<FeediyoContextValue>(
    () => ({
      identify: (u: IdentifyPayload | null) => {
        if (typeof window !== "undefined") {
          clientTokenRef.current = u?.clientToken ?? null;
          window.feediyo.identify(u);
        }
      },
      showWidget: () => {
        if (typeof window !== "undefined") window.feediyo.showWidget();
      },
      hideWidget: () => {
        if (typeof window !== "undefined") window.feediyo.hideWidget();
      },
      setTheme: (t: Theme) => {
        if (typeof window !== "undefined") window.feediyo.setTheme(t);
      },
      createAutoLoginUrl: (href: string) => {
        const token = clientTokenRef.current;
        if (!token) return href;
        try {
          const url = new URL(href);
          url.searchParams.set("_fdy", token);
          return url.toString();
        } catch {
          return href;
        }
      },
    }),
    [],
  );

  return <FeediyoContext.Provider value={value}>{children}</FeediyoContext.Provider>;
}

// ─── Hook ────────────────────────────────────────────────────────────────────

/**
 * Access Feediyo methods — for programmatic show/hide, theme changes,
 * and generating automatic login URLs for public board links.
 *
 * Must be called inside <FeediyoProvider>.
 *
 * @example
 * const { createAutoLoginUrl, showWidget } = useFeediyo();
 *
 * <a href={createAutoLoginUrl("https://feedback.example.com")}>
 *   View roadmap
 * </a>
 */
export function useFeediyo(): FeediyoContextValue {
  const ctx = useContext(FeediyoContext);
  if (!ctx) throw new Error("useFeediyo must be called inside <FeediyoProvider>.");
  return ctx;
}
